    "Beneficiary": "Moamohedi",
    "Reference": "Tshupiso",
    "Always use this reference: it is how Church Hub knows the payment is from your church.": "Kamehla sebedisa tshupiso ena: ke kamoo Church Hub e tsebang hore tefo e tswa kerekeng ya lona.",
    "From outside South Africa: use SWIFT code {swift} and the account holder’s name {name}. Your bank changes your money into rand.": "Ho tswa ka ntle ho Afrika Borwa: sebedisa khoutu ya SWIFT {swift} le lebitso la mong’a akhaonto {name}. Banka ya hao e fetola tjhelete ya hao ho ranta.",
    "From outside South Africa: your bank needs Capitec’s SWIFT code ({swift}) and the account holder’s full name. Write to Church Hub for these before you pay.": "Ho tswa ka ntle ho Afrika Borwa: banka ya hao e hloka khoutu ya SWIFT ya Capitec ({swift}) le lebitso le feletseng la mong’a akhaonto. Ngolla Church Hub bakeng sa tsena pele o lefa.",
    "Church Hub never sees your card or your bank details. It can take a few days for a payment to show.": "Church Hub ha e bone karete ya hao kapa dintlha tsa hao tsa banka. Ho ka nka matsatsi a mmalwa hore tefo e bonahale.",
    "In the prayer circle": "Sedikadikweng sa thapelo",
    "Christians in your country can face danger. Show your church’s name, town and photo to other churches anyway?": "Bakreste naheng ya hao ba ka tobana le kotsi. O bontshe dikereke tse ding lebitso la kereke ya lona, toropo le setshwantsho leha ho le jwalo?",
    "This month we pray for": "Kgweding ena re rapella",
    "Tick the promise first.": "Tshwaya tshepiso pele.",
    "Thank you – your church is in the prayer circle.": "Re a leboha – kereke ya lona e sedikadikweng sa thapelo.",
    "Click again: leave the prayer circle": "Tobetsa hape: tlohela sedikadikwe sa thapelo",
