    "Reply to {name}": "Araba {name}",
    "Only {name} will see your reply.": "Ke {name} feela ya tla bona karabo ya hao.",
    "Your reply": "Karabo ya hao",
    "Only {name} will see it.": "Ke {name} feela ya tla o bona.",
    "You can read the messages the church sends you here.": "O ka bala mona melaetsa eo kereke e o romellang yona.",
    "Ministers": "Baruti",
    "Midweek Group leaders": "Baetapele ba dihlopha tsa bophelo",
    "Couldn’t send the reply.": "Karabo ha e a kgona ho romelwa.",
    "Attendees": "Ba tlang kerekeng",
    "What people who aren’t Church Partners can do": "Seo batho bao e seng Balekane ba Kereke ba ka se etsang",
    "See the names of Church Partners": "Ho bona mabitso a Balekane ba Kereke",
    "Names only, on the People page – no photos, phone numbers or addresses.": "Mabitso feela, leqepheng la Batho – ha ho difoto, dinomoro tsa mohala kapa diaterese.",
    "See the church directory": "Ho bona bukana ya kereke",
    "As Church Partners see it: photos and the contact details people agreed to share.": "Jwalo ka ha Balekane ba Kereke ba e bona: difoto le dintlha tsa ho ikopanya tseo batho ba dumetseng ho di arolelana.",
    "Write to the Office, the ministers and their Midweek Group leaders": "Ho ngolla ofisi, baruti le baetapele ba dihlopha tsa bona tsa bophelo",
    "A message to one of them. They can also reply to a minister.": "Molaetsa ho e mong wa bona. Ba ka boela ba araba moruti.",
    "Reply to any message sent to them": "Ho araba molaetsa ofe kapa ofe o ba romelletsweng",
    "Otherwise they only read the messages the church sends them.": "Ho seng jwalo ba bala feela melaetsa eo kereke e ba romellang yona.",
    "People on Basic access who aren’t Church Partners or staff – usually people who come to church and have the app. Church Partners on Basic access get {access} automatically: they see the church directory and can reply to messages.": "Batho ba nang le phihlello ya motheo bao e seng Balekane ba Kereke kapa basebetsi – hangata batho ba tlang kerekeng mme ba na le app. Balekane ba Kereke ba nang le phihlello ya motheo ba fumana {access} ka bo yona: ba bona bukana ya kereke mme ba ka araba melaetsa.",
    "Now: {a} attendees and {p} Church Partners on Basic access who can sign in.": "Hona jwale: ba tlang kerekeng ba {a} le Balekane ba Kereke ba {p} ba nang le phihlello ya motheo ba ka kenang.",
    "Everyone always sees their own details, the rosters they are on and the messages sent to them.": "Motho e mong le e mong o lula a bona dintlha tsa hae, manane ao a leng ho ona le melaetsa e mo romelletsweng.",
    "Church Partners on Basic access get {access} automatically. Others on Basic access are attendees:": "Balekane ba Kereke ba nang le phihlello ya motheo ba fumana {access} ka bo yona. Ba bang ba nang le phihlello ya motheo ke ba tlang kerekeng:",
    "what attendees can do": "seo ba tlang kerekeng ba ka se etsang",
    "Do you think of {church} as your home church? Then we’d love you to become a {partner}.": "Na o nka {church} e le kereke ya hao ya lehae? Re ka thabela haholo hore o be {partner}.",
    "What becoming a {partner} involves": "Seo ho ba {partner} ho se kenyelletsang",
    "What it takes to become a {partner}": "Se hlokahalang ho ba {partner}",
    "Shown on the Me page of everyone who isn’t a Church Partner yet, with the button to apply. Write it here, link to a Google Doc, or attach a Word file or PDF.": "E bontshwa leqepheng la Nna la bohle bao e seng Balekane ba Kereke hajwale, le konopo ya ho etsa kopo. E ngole mona, hokahanya le Google Doc, kapa o kenye faele ya Word kapa PDF.",
    "Last changed by {name}": "E qetetse ho fetolwa ke {name}",
    "Nothing written yet.": "Ha ho se so ngolwang.",
    "Write the requirements": "Ngola ditlhoko",
    "Write or paste it here": "E ngole kapa o e kenye mona",
    "e.g. Be 18 or older, worship here regularly, come to a membership class…": "mohl. Ho ba le dilemo tse 18 kapa ho feta, ho rapela mona kamehla, ho tla tlelaseng ya botho…",
    "Or a link to it (e.g. a Google Doc shared with everyone who has the link)": "Kapa kgokahanyo ho yona (mohl. Google Doc e arolelanweng le bohle ba nang le kgokahanyo)",
    "The link should start with https://": "Kgokahanyo e lokela ho qala ka https://",
    "Write something, add a link or choose a file.": "Ngola ho hong, kenya kgokahanyo kapa o kgethe faele.",
    "The names of the church’s Church Partners.": "Mabitso a Balekane ba Kereke ba kereke.",
    "Purge library record": "Hlakola rekoto ya laeborari ruri",
    "Permanently delete this library record? This cannot be undone.": "Na o hlakole rekoto ye ya laeborari ruri? O ka se kgone go e busetsa morago.",
    "Permanently delete this book and its loan records? This cannot be undone.": "Na o hlakole puku ye le direkoto tša yona tša kadimo ruri? O ka se kgone go e busetsa morago.",
    "Fills in the three words below; you can still change each one.": "E tlatsa mantswe a mararo a ka tlase; o ntse o ka fetola le leng le le leng.",
    "Added – give it a name": "E kentswe – e fe lebitso",
    "An email to each person with leave they’ll lose if they don’t take it. Open each, check it and send it.": "Imeile ho motho ka mong ya nang le phomolo eo a tla e lahlehelwa haeba a sa e nke. Bula e nngwe le e nngwe, e hlahlobe mme o e romele.",
    "Write the email": "Ngola imeile",
    "No email address": "Ha ho aterese ya imeile",
    "Done – mark the reminders as sent": "Ho phethilwe – tshwaya dikgopotso di rometswe",
    "Let them know by email": "Ba tsebise ka imeile",
    "Good morning everyone,": "Dumelang bohle,",
    "Away this week ({from} – {to}):": "Ba seyo bekeng ena ({from} – {to}):",
    "No one is away this week.": "Ha ho ya seyo bekeng ena.",
    "Email the staff who is away this week": "Romela basebetsi imeile ka ba seyo bekeng ena",
    "Send the “use it or lose it” leave reminders": "Romela dikgopotso tsa phomolo tsa “e sebedise kapa o e lahlehelwe”",
    "Who’s away this week": "Ba seyo bekeng ena",
    "Then click “Mark as sent” on the Dashboard so it isn’t suggested again this week.": "Ebe o tobetsa “Tshwaya e rometswe” ho Dashboard hore e se ke ya hlahiswa hape bekeng ena.",
    "This week’s “who’s away” email hasn’t been sent yet.": "Imeile ya bekeng ena ya “ba seyo” ha e so romelwe.",
    "Write it": "E ngole",
    "Mark as sent": "Tshwaya e rometswe",
    "Your leave: use it or lose it": "Phomolo ya hao: e sebedise kapa o e lahlehelwe",
    "Dear {name},": "Dumela {name},",
    "A reminder that this leave will be lost if it isn’t taken in time:": "Kgopotso ya hore phomolo ena e tla lahleha haeba e sa nkuwe ka nako:",
    "take it by {date}": "e nke pele ho {date}",
    "You can book it in Church Hub under Leave.": "O ka e behela ho Church Hub tlasa Phomolo.",
    "Leave request: {name}, {dates}": "Kopo ya phomolo: {name}, {dates}",
