    "No one has leave about to be lost.": "Ha ho motho ya nang le phomolo e tla lahleha haufinyane.",
    "Busiest months": "Dikgwedi tse phathahaneng haholo",
    "None": "Ha ho letho",
    "Approved working days off each month, by kind of leave.": "Matsatsi a mosebetsi a dumeletsweng a phomolo kgwedi ka nngwe, ka mofuta wa phomolo.",
    "Sick leave this year": "Phomolo ya bokudi selemong sena",
