    "An employer may ask for a medical certificate": "Mohiri a ka kopa setifikeiti sa ngaka",
    "South African law lets an employer ask for a medical certificate when someone is off sick for more than 2 days in a row, or more than twice in 8 weeks. Health information: only leave managers see this, and opening the Dashboard is logged.": "Molao wa Afrika Borwa o dumella mohiri ho kopa setifikeiti sa ngaka ha motho a kula matsatsi a fetang a 2 a latellana, kapa ho feta habedi dibekeng tse 8. Tlhahisoleseding ya bophelo: ke balaodi ba phomolo feela ba e bonang, mme ho bulwa ha Dashboard ho a ngolwa.",
