    "List": "Lenane",
    "A stand-in must be a Pastor, who can already see staff details.": "Ya emang sebakeng o tlameha ho ba Moruti, ya seng a ka bona dintlha tsa basebetsi.",
    "Stand-in approver": "Mohlahlobi ya emang sebakeng",
    "Going away? Choose someone to approve or decline leave between two dates. They can’t decide their own leave, and their access ends by itself after the last day.": "O a tsamaya? Kgetha motho ya tla amohela kapa a hane phomolo pakeng tsa matsatsi a mabedi. Ba ke ke ba etsa qeto ka phomolo ya bona, mme phihlello ya bona e fela ka bo yona kamora letsatsi la ho qetela.",
    "Set stand-in": "Beha ya emang sebakeng",
    "Cover rules and blocked days": "Melao ya ho koahela le matsatsi a thibetsweng",
    "Stop the church being left without the people it needs. “At least … on duty” checks how many are still working; “No leave” blocks days such as Christmas. Warn lets the request through with a warning; Block stops staff sending it. Administrators can always approve anyway.": "Thibela hore kereke e sale e se na batho bao e ba hlokang. “Bonyane … mosebetsing” e sheba hore na ke ba bakae ba ntseng ba sebetsa; “Ha ho phomolo” e thibela matsatsi a kang Keresemese. Lemosa e dumella kopo ka temoso; Thibela e thibela basebetsi ho e romela. Batsamaisi ba ka dula ba amohela leha ho le jwalo.",
    "e.g. Christmas services": "mohl. ditshebeletso tsa Keresemese",
    "Rule": "Molao",
    "At least … on duty": "Bonyane … mosebetsing",
    "No leave": "Ha ho phomolo",
    "All staff": "Basebetsi bohle",
    "If broken": "Ha o tlolwa",
    "Warn": "Lemosa",
    "Block": "Thibela",
    "Days of the week": "Matsatsi a beke",
    "None ticked = every day.": "Ha ho a tshwailweng = letsatsi le leng le le leng.",
    "Message for staff": "Molaetsa ho basebetsi",
    "On": "E butswe",
    "Next: {dates}": "E latelang: {dates}",
    "Remove this rule": "Tlosa molao ona",
    "From and To: a date every year (24 Dec), Easter-based (Easter-2 is Good Friday, Easter+1 Family Day), or one date (2026-11-27). Leave both empty for all year.": "Ho tloha le Ho fihlela: letsatsi selemo se seng le se seng (24 Dec), ho latela Easter (Easter-2 ke Labohlano le Lokileng, Easter+1 Letsatsi la Lelapa), kapa letsatsi le le leng (2026-11-27). Siya ka bobedi di le feela bakeng sa selemo kaofela.",
    "A pastor every Sunday": "Moruti Sontaha se seng le se seng",
    "Christmas": "Keresemese",
    "Easter": "Easter",
    "Another rule": "Molao o mong",
    "Check the From and To dates of “{name}”": "Hlahloba matsatsi a Ho tloha le Ho fihlela a “{name}”",
    "Every rule needs a name.": "Molao o mong le o mong o hloka lebitso.",
    "Choose the person and both dates": "Kgetha motho le matsatsi ka bobedi",
    "Stand-in set": "Ya emang sebakeng o behilwe",
    "They’ve left the church: hidden from lists, history kept": "Ba tlohetse kereke: ba patilwe manane, histori e bolokilwe",
    "Change the church’s settings": "Fetola disetting tsa kereke",
    "Give and take away app access (Basic access, Roster coordinator, Children’s ministry)": "Fa le ho tlosa phihlello ya app (Phihlello ya motheo, Mohokahanyi wa lenane, Tshebeletso ya bana)",
    "Check changes members ask for, move people to the Bin and delete their information": "Hlahloba diphetoho tseo ditho di di kopang, isa batho Moqomong mme o hlakole tlhahisoleseding ya bona",
    "See and change ID numbers": "Bona le ho fetola dinomoro tsa ID",
    "Approve leave, book leave for others and change the leave settings": "Amohela phomolo, behela ba bang phomolo mme o fetole disetting tsa phomolo",
    "Manage rosters, teams and services": "Laola manane, dihlopha le ditshebeletso",
    "Privacy: requests, breaches, the audit log, exporting someone’s data": "Lekunutu: dikopo, ho tlolwa, rekoto ya tlhahlobo, ho romela data ya motho",
    "Import from Elvanto and Leave Manager, and the Elvanto robot": "Kenya ho tswa ho Elvanto le Leave Manager, le roboto ya Elvanto",
    "Approve better wording in every language": "Amohela mantswe a betere ka dipuo tsohle",
    "What Pastors can do": "Seo Baruti ba ka se etsang",
    "Senior Pastor": "Moruti e Moholo",
    "Assistant Pastor": "Mothusi wa Moruti",
    "Assistant Pastors": "Bathusi ba Baruti",
    "Nobody – all Pastors the same": "Ha ho motho – Baruti bohle ba a tshwana",
    "The Pastor who leads the church can have more than the others. The other Pastors are then called Assistant Pastors.": "Moruti ya etellang kereke pele a ka ba le ho feta ba bang. Baruti ba bang ebe ba bitswa Bathusi ba Baruti.",
    "The Pastor who leads the church (chosen in Settings → What Pastors can do)": "Moruti ya etellang kereke pele (o kgethwa ho Disetting → Seo Baruti ba ka se etsang)",
    "The other Pastors, who work with the Senior Pastor": "Baruti ba bang, ba sebetsang le Moruti e Moholo",
    "Pastors always see and edit everyone’s details, households, children and pastoral notes. Tick what else they may do – up to everything an Administrator does. Medical notes stay with Children’s ministry.": "Baruti kamehla ba bona le ho fetola dintlha tsa bohle, malapa, bana le dintlha tsa boruti. Tshwaya seo ba ka se etsang hape – ho fihlela ho tsohle tseo Motsamaisi a di etsang. Dintlha tsa bongaka di dula le Tshebeletso ya bana.",
    "Tick everything": "Tshwaya tsohle",
    "Pastors get the change the next time they open Church Hub.": "Baruti ba fumana phetoho ha ba bula Church Hub hape.",
    "If you have changed the database rules file, publish it again first (FIREBASE-SETUP step 7).": "Haeba o fetotse faele ya melao ya database, e phatlalatse hape pele (FIREBASE-SETUP mohato 7).",
    "Only Administrators can use the Bin.": "Ke Batsamaisi feela ba ka sebedisang Moqomo.",
    "Bin": "Moqomo",
    "People moved to the Bin are hidden everywhere and can’t sign in. Restore them within {n} days; after that they are deleted for good.": "Batho ba Moqomong ba patilwe hohle mme ba ke ke ba kena. Ba kgutlise nakong ya matsatsi a {n}; ka mora moo ba hlakolwa ka ho sa feleng.",
    "Moved to the Bin {date} by {name} · deleted on {gone}": "Ho isitswe Moqomong {date} ke {name} · ho hlakolwa ka {gone}",
    "Served on a roster or took leave: an anonymous record will be kept": "O sebeditse lenaneong la tshebeletso kapa o nkile phomolo: rekoto e se nang lebitso e tla bolokwa",
    "Restore": "Kgutlisa",
    "Delete forever": "Hlakola ka ho sa feleng",
    "The Bin is empty.": "Moqomo ha o na letho.",
    "You can’t move yourself to the Bin": "O ke ke wa ikisa Moqomong",
    "Click again: move to the Bin": "Tobetsa hape: isa Moqomong",
    "{name} moved to the Bin. Restore them from People → Bin within {n} days.": "{name} o isitswe Moqomong. Mo kgutlise ho Batho → Moqomo nakong ya matsatsi a {n}.",
    "{name} restored": "{name} o kgutlisitswe",
    "Click again: delete forever": "Tobetsa hape: hlakola ka ho sa feleng",
