    "Your current preference is {how}. Choose a new option only if you want to change it.": "Kgetho ya hao ya hajwale ke {how}. Kgetha kgetho e ntjha feela haeba o batla ho e fetola.",
    "Add any days you’re unavailable under Days away. You won’t be asked or scheduled to serve then.": "Kenya matsatsi ao o sa fumanehang ka tlasa Matsatsi a ho ba siyo. O ke ke wa kopuwa kapa wa beelwa ho sebeletsa ka nako eo.",
    "Office": "Ofisi",
