    "Read: everyone has read it.": "O badilwe: bohle ba o badile.",
    "A message to the Office counts as read as soon as someone in the office reads it.": "Molaetsa o yang Ofising o nkuwa o badilwe hang ha motho e mong ofising a o bala.",
