    "The weekly notices by email.": "Ditsebiso tsa beke ka imeile.",
    "Prayer needs, sent on WhatsApp.": "Ditlhoko tsa thapelo, di romelwa ka WhatsApp.",
    "Prayer needs, sent by email.": "Ditlhoko tsa thapelo, di romelwa ka imeile.",
    "News from the church’s missionaries, on WhatsApp.": "Ditaba tse tswang ho baromuwa ba kereke, ka WhatsApp.",
    "News from the church’s missionaries, by email.": "Ditaba tse tswang ho baromuwa ba kereke, ka imeile.",
    "A two minute WhatsApp message from Richard Sturdee, focussing on the person and work of our Lord Jesus Christ.": "Molaetsa wa WhatsApp wa metsotso e mmedi o tswang ho Richard Sturdee, o shebaneng le botho le mosebetsi wa Morena wa rona Jesu Kreste.",
