    "A spreadsheet saved as CSV, with a heading on each column: Title (needed), and any of Author, Type, Category, Copies, Shelf, ISBN, Date acquired, How acquired, Donated by, Note.": "Spreadsheet e bolokiloeng e le CSV, ka hlooho kholomong e 'ngoe le e 'ngoe: Title (e hlokahalang), le e 'ngoe ea Author, Type, Category, Copies, Shelf, ISBN, Date acquired, How acquired, Donated by, Note.",
    "Church Hub couldn’t find a Title column. The first row must hold the headings, one of them Title.": "Church Hub ha e fumane kholomo ea Title. Mola oa pele o tlameha ho ba le lihlooho, e 'ngoe ea tsona e be Title.",
