    "No Midweek Groups yet.": "Ha ho dihlopha tsa bophelo hajoale.",
    "Midweek Group added": "Sehlopha sa bophelo se kentswe",
    "Midweek Group deleted": "Sehlopha sa bophelo se hlakotswe",
    "You’re not in a Midweek Group yet. Ask the church office or a group leader to add you.": "Ha o eso be sehlopheng sa bophelo. Kopa ofisi ya kereke kapa moetapele wa sehlopha hore a o kenye.",
    "People in your Midweek Group see your details only if you are in the church directory (under Consent).": "Batho ba sehlopheng sa hao sa bophelo ba bona dintlha tsa hao feela ha o le Bukaneng ya kereke (tlasa Tumello).",
    "Bible studies, life groups, Connect Groups and other Midweek Groups. A person can be in more than one. Members see each other’s photo, phone, email, address and birthday if they are in the church directory. Group leaders can name their group and add and remove members.": "Dithuto tsa Bibele, dihlopha tsa bophelo le dikopano tsa bohareng ba beke. Motho a ka ba ho tse fetang se le seng. Ditho di bona setshwantsho, mohala, imeile, aterese le letsatsi la tswalo la ba bang ha ba le Bukaneng ya kereke. Baetapele ba dihlopha ba ka rea sehlopha sa bona lebitso, ba kenya le ho ntsha ditho.",
    "Bible studies, life groups, Connect Groups – their leaders name them": "Dithuto tsa Bibele, dihlopha tsa bophelo le dihlopha tsa bohareng ba beke – baetapele ba tsona ba di rea mabitso",
    "A Bible Study, Life Group or Connect Group (etc) that meets during the week for teaching and fellowship": "Thuto ya Bibele, sehlopha sa bophelo kapa Connect Group (jj.) se kopanang hara beke bakeng sa thuto le kopano",
    "Someone who leads a Midweek Group": "Motho ya etellang sehlopha sa bophelo pele",
    "{n} person in a Care Group isn’t in the church directory, so Church Partners don’t see them on the Care Groups page.": "Motho ya {n} sehlopheng sa tlhokomelo ha a lenaneng la kereke, ka hona Balekane ba Kereke ha ba mmone leqepheng la dihlopha.",
    "{n} people in Care Groups aren’t in the church directory, so Church Partners don’t see them on the Care Groups page.": "Batho ba {n} dihlopheng tsa tlhokomelo ha ba lenaneng la kereke, ka hona Balekane ba Kereke ha ba ba bone leqepheng la dihlopha.",
    "Show them": "Ba bontshe",
    "Contact details not asked yet": "Ha ba so botswe ka dintlha tsa kgokahano",
    "“Record that they agreed” records it for Church Partners; for anyone else, record their answer on their profile (Consent).": "“Ngola hore ba dumetse” e ngolla Balekane ba Kereke; ho ba bang, ngola karabo ya bona profaeleng ya bona (Tumello).",
    "Said no to sharing their contact details": "O hanne ho arolelana dintlha tsa kgokahano",
    "They stay hidden unless they change their mind (their profile → Consent).": "Ba dula ba patilwe ntle le haeba ba fetola maikutlo (profaele ya bona → Tumello).",
    "No longer active": "Ha a sa sebetsa",
    "Take them out of their Care Group, or mark them active again.": "Ba ntshe sehlopheng sa bona, kapa o ba tshwaye e le ba sebetsang hape.",
    "Children are never shown to other members.": "Bana ha ba bontshwe ditho tse ding.",
    "In Care Groups, but not in the church directory": "Dihlopheng tsa tlhokomelo, empa ha ba lenaneng la kereke",
    "Their own group: see all its members": "Sehlopha sa bona: bona ditho tsohle",
