    "No Care Group or person matches what you typed.": "Ha ho sehlopha sa tlhokomelo kapa motho ya tsamaellanang le seo o se ngotseng.",
    "Back to {role}": "Kgutlela ho {role}",
    "Agreed on becoming a Church Partner": "O dumetse ha a eba Molekane wa Kereke",
    "{n} Church Partner has no Contact details answer recorded. If they agreed when they became a Church Partner, record it here.": "Molekane wa Kereke ya {n} ha a na karabo e ngotsweng ka Dintlha tsa kgokahano. Haeba ba dumetse ha ba eba Molekane wa Kereke, e ngole mona.",
