    "Administrators only. Keep it only if the church still needs it ({law}).": "Batsamaisi feela. E boloke feela haeba kereke e ntse e e hloka ({law}).",
    "South African ID numbers have 13 digits. Passport numbers are fine too.": "Dinomoro tsa ID tsa Afrika Borwa di na le dinomoro tse 13. Dinomoro tsa phasepoto le tsona di lokile.",
    "Remove the ID number": "Tlosa nomoro ya ID",
    "That doesn’t look like an ID or passport number.": "Seo ha se bonahale jwalo ka nomoro ya ID kapa ya phasepoto.",
    "ID number removed": "Nomoro ya ID e tlositswe",
    "ID number saved": "Nomoro ya ID e bolokilwe",
