    "e.g. Naidoo": "mohl. Naidoo",
    "Once adults are added, the household is named after them automatically (e.g. “Jason & Priya Naidoo”).": "Ha batho ba baholo ba eketswa, lelapa le bitswa ka mabitso a bona ka bolona (mohl. “Jason & Priya Naidoo”).",
    "Create": "Theha",
    "Won’t be suggested again": "E ke ke ya hlahiswa hape",
