    "Please fill in every box.": "Ka kopo tlatsa mabokose kaofela.",
    "Setting up didn’t work ({code}). Check the rules were published (setup guide, step 7).": "Ho hlophisa ha ho a sebetsa ({code}). Hlahloba hore melao e phatlaladitswe (tataiso ya ho hlophisa, mohato wa 7).",
    "Demo data reset": "Data ya teko e kgutlisitswe",
    "View as another role…": "Bona jwalo ka karolo e nngwe…",
    "See what other people see when they sign in": "Bona seo batho ba bang ba se bonang ha ba kena",
    "You stay signed in as yourself, but Church Hub shows only what that role may see.": "O dula o kene jwalo ka wena, empa Church Hub e bontsha feela seo karolo eo e dumelletsweng ho se bona.",
    "Nothing you do is saved while you’re viewing. Pastoral and medical notes stay hidden – only Pastors and Children’s ministry may see those.": "Ha ho letho le bolokwang ha o ntse o sheba. Dintlha tsa boruti le tsa bongaka di dula di patilwe – ke Baruti le Bosebeletsi ba bana feela ba ka di bonang.",
    "There are no Care Groups yet – add them on the Care Groups page": "Ha ho dihlopha tsa tlhokomelo hajwale – di kenye leqepheng la Dihlopha tsa tlhokomelo",
    "View as a carer": "Bona jwalo ka mohlokomedi",
    "Which Care Group?": "Sehlopha sefe sa tlhokomelo?",
    "See the group the way its carer does, on their Me page.": "Bona sehlopha kamoo mohlokomedi wa sona a se bonang kateng, leqepheng la bona la Nna.",
    "Viewing as {role} – nothing is saved": "O sheba jwalo ka {role} – ha ho letho le bolokwang",
    "Loading what {role} sees…": "Ho jarollwa seo {role} a se bonang…",
    "Back to Administrator…": "Ho kgutlelwa ho Motsamaisi…",
    "Bringing in photos from Elvanto: {n} of {total}. Please keep this page open.": "Ho tliswa ditshwantsho ho tswa Elvanto: {n} ho {total}. Ka kopo tlohela leqephe lena le butswe.",
    "Photos:": "Ditshwantsho:",
    "{n} brought in from Elvanto": "{n} di tlisitswe ho tswa Elvanto",
    "{n} couldn’t be downloaded (they can be added by hand on each person’s page)": "{n} ha di a kgona ho jarollwa (di ka kenngwa ka letsoho leqepheng la motho e mong le e mong)",
    "Unavailable dates from Elvanto": "Matsatsi a ho se fumanehe ho tswa Elvanto",
    "Who is unavailable in Elvanto, read by the robot every night. Check them and add them to Church Hub as away dates, so rosters here know too. Nothing is changed in Elvanto.": "Ke mang ya sa fumaneheng ho Elvanto, ho balwa ke roboto bosiu bo bong le bo bong. A hlahlobe mme o a kenye ho Church Hub jwalo ka matsatsi a ho ba siyo, e le hore le manane a mona a tsebe. Ha ho letho le fetolwang ho Elvanto.",
    "The robot hasn’t read Elvanto yet – it does so every night at about 3am.": "Roboto ha e eso bale Elvanto – e etsa jwalo bosiu bo bong le bo bong ka hora ya 3 hoseng.",
    "Switch this on under {link} (“Read Elvanto’s unavailable dates every night”). The robot needs to be set up first – see the guide in docs/ELVANTO-ROBOT.md.": "Bulela sena tlasa {link} (“Bala matsatsi a ho se fumanehe a Elvanto bosiu bo bong le bo bong”). Roboto e lokela ho hlophiswa pele – bona tataiso ho docs/ELVANTO-ROBOT.md.",
    "Leave → Elvanto": "Phomolo → Elvanto",
    "Read {when}": "E badilwe {when}",
    "{n} entries from today on": "Dikeno tse {n} ho tloha kajeno",
    "{n} row(s) the robot couldn’t read – check those in Elvanto": "Methaladi e {n} eo roboto e hlolehileng ho e bala – e hlahlobe ho Elvanto",
    "Add {n} away date": "Kenya letsatsi le {n} la ho ba siyo",
    "Add {n} away dates": "Kenya matsatsi a {n} a ho ba siyo",
    "Add this": "Kenya sena",
    "The name in Elvanto matches more than one person in Church Hub, or no one exactly.": "Lebitso le ho Elvanto le tshwana le motho ya fetang a le mong ho Church Hub, kapa ha le tshwane hantle le motho.",
    "No one is unavailable in Elvanto from today on.": "Ha ho ya sa fumaneheng ho Elvanto ho tloha kajeno.",
    "Import from": "Kenya ho tswa ho",
    "From Leave Manager": "Ho tswa ho Leave Manager",
    "Import from Elvanto": "Kenya ho tswa Elvanto",
    "Bring your people and households (Elvanto’s “families”) across from Elvanto. Nothing is changed in Elvanto.": "Tlisa batho ba hao le malapa (“malapa” a Elvanto) ho tswa Elvanto. Ha ho letho le fetolwang ho Elvanto.",
    "Imported.": "Ho kentswe.",
    "{a} added, {u} updated, {f} households created.": "{a} ba kentswe, {u} ba ntjhafaditswe, malapa a {f} a thehilwe.",
    "{n} volunteering positions.": "Maemo a {n} a boithaopo.",
    "{n} “would like to receive” choices.": "Dikgetho tse {n} tsa “a ka rata ho amohela”.",
    "Positions Church Hub doesn’t have (left out): {list}.": "Maemo ao Church Hub e se nang ona (a tlohetswe): {list}.",
