    "Open People": "Bula Batho",
    "Import another file": "Kenya faele e nngwe",
    "1. Export from Elvanto": "1. Ntsha ho tswa Elvanto",
    "In Elvanto, open {people} and clear the filters so everyone is listed.": "Ho Elvanto, bula {people} mme o tlose difilthara hore bohle ba thathamiswe.",
    "Choose {export} → {csv}.": "Kgetha {export} → {csv}.",
    "Export": "Ntsha",
    "Church Hub reads only:": "Church Hub e bala feela:",
    "Member ID": "ID ya setho",
    "Photo": "Setshwantsho",
    "(downloaded from Elvanto and made small), ID Number (Administrators only), Notes (church office notes), Checklist of what to receive, Department Positions (volunteering) and the home address. Everything else (groups, giving, security codes…) is ignored – but it’s safer to leave those columns out of the export.": "(se jarollotswe ho tswa Elvanto mme sa etswa se senyane), Nomoro ya ID (Batsamaisi feela), Dintlha (dintlha tsa ofisi ya kereke), Lenane la seo ba se amohelang, Maemo a mafapha (boithaopo) le aterese ya lehae. Tse ding kaofela (dihlopha, dikabelo, dikhoutu tsa tshireletso…) ha di natswe – empa ho bolokehile ho tlohela dikholomo tseo ha di ntshwa.",
    "Keep the file on the church computer and delete it once imported – it contains personal information.": "Boloka faele khomphutareng ya kereke mme o e hlakole ha e se e kentswe – e na le tlhahisoleseding ya motho.",
