    "{n} email address is shared by more than one person (e.g. a couple). They stay separate people.": "Aterese e {n} ya imeile e sebediswa ke motho ya fetang a le mong (mohl. banyalani). Ba dula e le batho ba fapaneng.",
    "{n} email addresses are shared by more than one person (e.g. a couple). They stay separate people.": "Diaterese tse {n} tsa imeile di sebediswa ke motho ya fetang a le mong (mohl. banyalani). Ba dula e le batho ba fapaneng.",
    "In Church Hub": "Ho Church Hub",
    "Categories": "Mafapha",
    "What each Elvanto category becomes in Church Hub.": "Seo lefapha le leng le le leng la Elvanto le fetohang sona ho Church Hub.",
    "Elvanto records show these people agreed to the church keeping their details.": "Direkoto tsa Elvanto di bontsha hore batho bana ba dumetse hore kereke e boloke dintlha tsa bona.",
    "That file has no rows to import": "Faele eo ha e na methaladi ya ho kenngwa",
    "Import from Leave Manager": "Kenya ho tswa ho Leave Manager",
    "Bring staff leave across from the Leave Manager Google Sheet: booked and past leave, carried-over days and the leave settings. Nothing is changed in the sheet.": "Tlisa phomolo ya basebetsi ho tswa Google Sheet ya Leave Manager: phomolo e hlophisitsweng le e fetileng, matsatsi a fetisitsweng le disetting tsa phomolo. Ha ho letho le fetolwang ho sheet.",
    "{a} leave requests added, {u} updated, {j} adjustments": "Dikopo tse {a} tsa phomolo di kentswe, {u} di ntjhafaditswe, diphetoho tse {j}",
    "{n} new staff added to People": "Basebetsi ba batjha ba {n} ba kentswe ho Batho",
    "{n} requests skipped (staff not brought across).": "Dikopo tse {n} di tlohetswe (basebetsi ha ba a tliswa).",
    "Check {link} against Leave Manager. You can run the import again just before switching over: leave already brought in is updated, not doubled.": "Bapisa {link} le Leave Manager. O ka kenya hape pele ho fetola: phomolo e seng e tlisitswe ya ntjhafatswa, ha e phetwe habedi.",
