    "Team balances": "Masala a sehlopha",
    "Import again": "Kenya hape",
    "1. Download the sheet": "1. Jarolla sheet",
    "Open the {sheet} Google Sheet.": "Bula Google Sheet ya {sheet}.",
    "Click {menu}.": "Tobetsa {menu}.",
    "File → Download → Microsoft Excel (.xlsx)": "File → Download → Microsoft Excel (.xlsx)",
    "Come back here and choose that file.": "Kgutlela mona mme o kgethe faele eo.",
    "Or download each tab as {csv} (File → Download → Comma-separated values) and choose them all at once. PINs are never brought across.": "Kapa jarolla thebe ka nngwe jwalo ka {csv} (File → Download → Comma-separated values) mme o di kgethe kaofela hang. Di-PIN ha di tliswe le ka mohla.",
    "The file holds staff leave and reasons – keep it on the church computer and delete it once imported.": "Faele e na le phomolo ya basebetsi le mabaka – e boloke khomphutareng ya kereke mme o e hlakole ha e se e kentswe.",
    "Leave Manager download (.xlsx or .csv files)": "Se jarollotsweng ho Leave Manager (difaele tsa .xlsx kapa .csv)",
    "Reading…": "Ho a balwa…",
    "try it with a made-up Leave Manager sheet": "leka ka sheet ya Leave Manager e entsweng",
    "Read: {files} – found {tabs}.": "E badilwe: {files} – ho fumanwe {tabs}.",
    "Missing tabs: {tabs}. Download the whole sheet as Excel, or include those CSV files.": "Dithebe tse haellang: {tabs}. Jarolla sheet kaofela jwalo ka Excel, kapa o kenyelle difaele tseo tsa CSV.",
    "In Leave Manager": "Ho Leave Manager",
    "Church Hub person": "Motho wa Church Hub",
