    "Don’t bring across": "O se ke wa tlisa",
    "Leave requests": "Dikopo tsa phomolo",
    "Adjustments": "Diphetoho",
    "Use the sheet’s settings: kinds of leave, categories and allowances, school terms, public holidays and cover rules": "Sebedisa disetting tsa sheet: mefuta ya phomolo, mafapha le ditokelo, dikotara tsa sekolo, matsatsi a phomolo a setjhaba le melao ya ho emela",
    "(replaces what’s in Leave → Settings)": "(e nka sebaka sa se ho Phomolo → Disetting)",
    "Update staff details (category, start date, working days) from the sheet": "Ntjhafatsa dintlha tsa basebetsi (lefapha, letsatsi la ho qala, matsatsi a ho sebetsa) ho tswa ho sheet",
    "Leave already in Church Hub stays. Running this again later updates what was brought in, without doubling it.": "Phomolo e seng e le ho Church Hub e a sala. Ho etsa sena hape hamorao ho ntjhafatsa se tlisitsweng, ntle le ho se pheta habedi.",
