    "Balances after importing ({year})": "Masala kamora ho kenya ({year})",
    "Compare these with {team} in Leave Manager – they should be the same, apart from any leave already booked in Church Hub itself.": "Bapisa tsena le {team} ho Leave Manager – di lokela ho tshwana, ntle le phomolo e seng e hlophisitswe ho Church Hub ka boyona.",
