    "Waiting for your decision": "Ho emetswe qeto ya hao",
    "Decline": "Hana",
    "Approve": "Dumela",
    "Nothing is waiting for approval.": "Ha ho letho le emetseng tumello.",
    "Download team balances": "Jarolla masala a sehlopha",
    "Click a name for that person’s leave in detail.": "Tobetsa lebitso ho bona phomolo ya motho eo ka botlalo.",
    "A dash in every column means that person’s staff category has no allowances yet – set them under Leave → Settings.": "Mola wa mahlakore kholomong e nngwe le e nngwe o bolela hore lefapha la basebetsi la motho eo ha le eso be le ditokelo – di hlophise tlasa Phomolo → Disetting.",
    "Approved leave goes into Elvanto’s {list} list, so nobody is rostered in Elvanto while they’re away. Elvanto can’t be updated directly, so a robot logs into Elvanto every 15 minutes and does it, like Leave Manager’s robot.": "Phomolo e dumeletsweng e ya lenaneng la {list} la Elvanto, e le hore ho se be le motho ya behwang lenaneng ho Elvanto ha a le siyo. Elvanto e ke ke ya ntjhafatswa ka kotloloho, kahoo roboto e kena ho Elvanto metsotso e meng le e meng e 15 mme e etse sena, jwalo ka roboto ya Leave Manager.",
    "Each entry has the note “Church Hub {id}”.": "Keno e nngwe le e nngwe e na le ntlha ya “Church Hub {id}”.",
    "request ID": "ID ya kopo",
    "Keep Elvanto up to date": "Boloka Elvanto e le ya hajwale",
    "Switch on when you stop using Leave Manager (switch Leave Manager’s robot off at the same time), so entries aren’t made twice.": "Bulela ha o tlohela ho sebedisa Leave Manager (tima roboto ya Leave Manager ka nako eo), e le hore dikeno di se ke tsa etswa habedi.",
    "Read Elvanto’s unavailable dates every night": "Bala matsatsi a ho se fumanehe a Elvanto bosiu bo bong le bo bong",
    "Until you switch over, the robot reads who is unavailable in Elvanto (names and dates only). Check and add them to Church Hub under {link}.": "Ho fihlela o fetola, roboto e bala hore ke mang ya sa fumaneheng ho Elvanto (mabitso le matsatsi feela). A hlahlobe mme o a kenye ho Church Hub tlasa {link}.",
    "Elvanto web address": "Aterese ya websaete ya Elvanto",
    "Robot’s Church Hub sign-in (email)": "Ho kena ha roboto ho Church Hub (imeile)",
    "e.g. robot@yourchurch.org": "mohl. robot@yourchurch.org",
    "The account you created for the robot in Firebase (see the setup guide).": "Akhaonto eo o e theheletseng roboto ho Firebase (bona tataiso ya ho hlophisa).",
    "Robot’s account ID (User UID)": "ID ya akhaonto ya roboto (User UID)",
    "Saved – type a new one to change it": "E bolokilwe – ngola e ntjha ho e fetola",
    "Copy it from Firebase → Authentication → Users": "E kopitse ho tswa Firebase → Authentication → Users",
